refsection.programlisting:
function y = my_field_size(F)
    gf_check_field(F, "my_field_size");
    y = gf_order(F);
endfunction

my_field_size(gf_create_field(5, 2))   // 25

try
    my_field_size(list(1, 2))
catch
    disp(lasterror())   // my_field_size: Wrong type for input argument #1: ...
end
